import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';

describe('ToolRegistry schema compilation and caching', () => {
  it('throws synchronously at register time naming the tool when a static inputSchema is invalid JSON Schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'bad_schema_tool',
          description: 'Invalid schema',
          inputSchema: {
            type: 'object',
            properties: {query: {type: 'unknown-type'}},
          },
        },
        async () => 'ok'
      )
    ).toThrow(/bad_schema_tool/);
  });

  it('compiles a static inputSchema once at register time without re-reading definition.inputSchema on execute', async () => {
    const registry = new ToolRegistry();
    let schemaReads = 0;
    const schema = {
      type: 'object',
      properties: {city: {type: 'string'}},
      required: ['city'],
    };
    const definition: ToolDefinition = {
      name: 'lookup_city',
      description: 'Look up a city',
      get inputSchema() {
        schemaReads += 1;
        return schema;
      },
    };

    registry.register(definition, async input => `found ${String(input.city)}`);
    const readsAtRegister = schemaReads;
    const first = await registry.execute('lookup_city', {city: 'Amsterdam'});
    const second = await registry.execute('lookup_city', {city: 'Rotterdam'});

    expect({
      readsAtRegister,
      readsAfterExecutes: schemaReads,
      firstResult: first.result,
      secondResult: second.result,
    }).toEqual({
      readsAtRegister: 1,
      readsAfterExecutes: 1,
      firstResult: 'found Amsterdam',
      secondResult: 'found Rotterdam',
    });
  });

  it('caches compiled validators by schema reference for a function-valued ToolDefinitionSource while enforcing distinct returned schemas', async () => {
    const registry = new ToolRegistry();
    let activeSchema: Record<string, unknown> = {
      type: 'object',
      properties: {city: {type: 'string'}},
      required: ['city'],
    };
    let sourceCalls = 0;

    registry.register(
      () => {
        sourceCalls += 1;
        return {
          name: 'dynamic_tool',
          description: 'Dynamic schema tool',
          inputSchema: activeSchema,
        };
      },
      async input => `ok:${Object.keys(input).join(',')}`
    );

    const first = await registry.execute('dynamic_tool', {city: 'Berlin'});
    const second = await registry.execute('dynamic_tool', {city: 'Munich'});
    activeSchema = {
      type: 'object',
      properties: {zip: {type: 'number'}},
      required: ['zip'],
    };
    const third = await registry.execute('dynamic_tool', {zip: 10115});

    expect({
      sourceCalls,
      first: first.result,
      second: second.result,
      third: third.result,
    }).toEqual({
      sourceCalls: 4,
      first: 'ok:city',
      second: 'ok:city',
      third: 'ok:zip',
    });
  });
});

