import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';
import {setLogger} from '../../shared/logger.js';
import type {Logger} from '../../shared/logger.js';

describe('ToolRegistry schema compilation and caching', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  it('throws synchronously at register time naming the tool when a static inputSchema is invalid JSON Schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'bad_schema_tool',
          description: 'Invalid schema',
          inputSchema: {
            type: 'object',
            properties: {query: {type: 'unknown-type'}},
          },
        },
        async () => 'ok'
      )
    ).toThrow(/bad_schema_tool/);
  });

  it('compiles a static inputSchema once at register time without re-reading definition.inputSchema on execute', async () => {
    const registry = new ToolRegistry();
    let schemaReads = 0;
    const schema = {
      type: 'object',
      properties: {city: {type: 'string'}},
      required: ['city'],
    };
    const definition: ToolDefinition = {
      name: 'lookup_city',
      description: 'Look up a city',
      get inputSchema() {
        schemaReads += 1;
        return schema;
      },
    };

    registry.register(definition, async input => `found ${String(input.city)}`);
    const readsAtRegister = schemaReads;
    const first = await registry.execute('lookup_city', {city: 'Amsterdam'});
    const second = await registry.execute('lookup_city', {city: 'Rotterdam'});

    expect({
      readsAtRegister,
      readsAfterExecutes: schemaReads,
      firstResult: first.result,
      secondResult: second.result,
    }).toEqual({
      readsAtRegister: 1,
      readsAfterExecutes: 1,
      firstResult: 'found Amsterdam',
      secondResult: 'found Rotterdam',
    });
  });

  it('caches compiled validators by schema reference for a function-valued ToolDefinitionSource while enforcing distinct returned schemas', async () => {
    const registry = new ToolRegistry();
    let activeSchema: Record<string, unknown> = {
      type: 'object',
      properties: {city: {type: 'string'}},
      required: ['city'],
    };
    let sourceCalls = 0;

    registry.register(
      () => {
        sourceCalls += 1;
        return {
          name: 'dynamic_tool',
          description: 'Dynamic schema tool',
          inputSchema: activeSchema,
        };
      },
      async input => `ok:${Object.keys(input).join(',')}`
    );

    const first = await registry.execute('dynamic_tool', {city: 'Berlin'});
    const second = await registry.execute('dynamic_tool', {city: 'Munich'});
    activeSchema = {
      type: 'object',
      properties: {zip: {type: 'number'}},
      required: ['zip'],
    };
    const staleRejected = await registry.execute('dynamic_tool', {city: 'Hamburg'});
    const third = await registry.execute('dynamic_tool', {zip: 10115});

    expect({
      sourceCalls,
      first: first.result,
      second: second.result,
      staleRejectedMentionsZip: staleRejected.result.includes('zip') && /required/i.test(staleRejected.result),
      third: third.result,
    }).toEqual({
      sourceCalls: 5,
      first: 'ok:city',
      second: 'ok:city',
      staleRejectedMentionsZip: true,
      third: 'ok:zip',
    });
  });

  it('rejects input missing a required field with a ToolResponse naming the field and without calling the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect({
      executorCalls,
      namesFieldAsRequired: response.result.includes('location') && /required/i.test(response.result),
    }).toEqual({
      executorCalls: 0,
      namesFieldAsRequired: true,
    });
  });

  it('rejects a wrong-typed property naming the field path and expected type without leaking the offending value to result or logs', async () => {
    const recordedLogs: string[] = [];
    const recordLine = (category: string, message: string, fields?: Record<string, unknown>) => {
      recordedLogs.push(JSON.stringify({category, message, fields}));
    };
    const logger: Logger = {
      debug: recordLine,
      info: recordLine,
      warn: recordLine,
      error: recordLine,
    };
    setLogger(logger);

    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'lookup_patient',
        description: 'Look up patient record',
        inputSchema: {
          type: 'object',
          properties: {patient_id: {type: 'string'}},
          required: ['patient_id'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'ok';
      }
    );

    const response = await registry.execute('lookup_patient', {patient_id: 987654321});

    expect({
      executorCalls,
      namesField: response.result.includes('patient_id'),
      namesType: response.result.includes('string'),
      leaksValueInResult: response.result.includes('987654321'),
      leaksValueInLogs: recordedLogs.some(line => line.includes('987654321')),
    }).toEqual({
      executorCalls: 0,
      namesField: true,
      namesType: true,
      leaksValueInResult: false,
      leaksValueInLogs: false,
    });
  });
});

import Ajv from 'ajv';
import type {ErrorObject, ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validate?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({format: false, allErrors: true});
  private readonly dynamicValidators = new WeakMap<Record<string, unknown>, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validate =
      typeof definition === 'function' ? undefined : compileInputSchema(this.ajv, resolved.name, resolved.inputSchema);
    this.tools.set(resolved.name, {definitionSource: definition, execute, validate});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  private validatorFor(tool: StoredTool): ValidateFunction {
    if (tool.validate) return tool.validate;
    const resolved = this.resolveDefinition(tool.definitionSource);
    const cached = this.dynamicValidators.get(resolved.inputSchema);
